    # Ensure only the first '=' splits key/value
    assert parse_kv("key=value=with=equals") == {"key": "value=with=equals"}

def test_invalid_pairs():
    # Should ignore pairs without '='
    assert parse_kv("valid=pair; invalid_pair; another=valid") == {"valid": "pair", "another": "valid"}

